import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import {
  IMAGE_SIZE_CONTRACT, bytesToBase64, decodedBytesOfBase64,
  imageContractViolations, legacyPhotoPayload, normalizePhotoFile,
  planNormalization,
} from '../src/app-image.js';

// Fixed image fixture. The bytes are generated by a seeded LCG so
// the fixture is identical on every run, and the SHA-256 pins below
// freeze what each pipeline makes of it. The photo bytes the client
// sends become the server-side thumbnail input (the observer
// coordinate derives from them), so if a change alters these
// hashes, it alters future targets' coordinates — update the pins
// only as a deliberate, recorded pipeline change.
function fixtureBytes(seed, length, head, tail) {
  const bytes = new Uint8Array(length);
  bytes.set(head, 0);
  let state = seed;
  for (let i = head.length; i < length - tail.length; i += 1) {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    bytes[i] = (state >> 8) & 0xff;
  }
  bytes.set(tail, length - tail.length);
  return bytes;
}

const FIXTURE_PHOTO = fixtureBytes(42, 4096, [0xff, 0xd8, 0xff, 0xe0], [0xff, 0xd9]);
const FIXTURE_PHOTO_SHA256 = '34cb803b3965ccba15e1a7aab69d312e54ea7ca7b1092e6ee581053a0a2152eb';
const FIXTURE_ENCODED = fixtureBytes(7, 2048, [0xff, 0xd8, 0xff, 0xe1], [0xff, 0xd9]);
const FIXTURE_ENCODED_SHA256 = '9f9e398421ee0769e4572f556002b74fc72592dee3ff3593d3533e2d4a3bf877';

const sha256Hex = (bytes) => createHash('sha256').update(bytes).digest('hex');
const base64ToBytes = (base64) => new Uint8Array(Buffer.from(base64, 'base64'));

test('legacy pipeline fixture: the payload is the file bytes, unchanged', () => {
  const dataUrl = 'data:image/jpeg;base64,' + bytesToBase64(FIXTURE_PHOTO);
  const payload = legacyPhotoPayload(dataUrl);
  assert.equal(payload, bytesToBase64(FIXTURE_PHOTO));
  assert.equal(sha256Hex(base64ToBytes(payload)), FIXTURE_PHOTO_SHA256);
  assert.equal(legacyPhotoPayload(''), '');
  assert.equal(legacyPhotoPayload('no-comma-here'), '');
});

test('planNormalization shrinks the long edge to 2048 and never upscales', () => {
  assert.deepEqual(planNormalization(4032, 3024), { width: 2048, height: 1536, resized: true });
  assert.deepEqual(planNormalization(3024, 4032), { width: 1536, height: 2048, resized: true });
  assert.deepEqual(planNormalization(8000, 100), { width: 2048, height: 26, resized: true });
  assert.deepEqual(planNormalization(2048, 100), { width: 2048, height: 100, resized: false });
  assert.deepEqual(planNormalization(1200, 900), { width: 1200, height: 900, resized: false });
  assert.deepEqual(planNormalization(100000, 1), { width: 2048, height: 1, resized: true });
});

// Deterministic stand-in for the browser codec: decode reports an
// iPhone-class 4032x3024 frame, encode returns the fixed fixture
// bytes and records the geometry it was asked for.
function fixtureCodec(calls) {
  return {
    async decode(file) {
      calls.push(['decode', file]);
      return { bitmap: { fixture: true }, width: 4032, height: 3024 };
    },
    async encode(request) {
      calls.push(['encode', request]);
      return new Blob([FIXTURE_ENCODED], { type: 'image/jpeg' });
    },
  };
}

test('normalized pipeline fixture: planned geometry, pinned output bytes and hash', async () => {
  const calls = [];
  const result = await normalizePhotoFile({ name: 'fixture.jpg' }, fixtureCodec(calls));
  assert.equal(result.ok, true);
  assert.equal(result.resized, true);
  assert.deepEqual([result.width, result.height], [2048, 1536]);
  const encode = calls.find(([kind]) => kind === 'encode')[1];
  assert.deepEqual([encode.width, encode.height], [2048, 1536]);
  assert.equal(encode.quality, IMAGE_SIZE_CONTRACT.jpegQuality);
  assert.equal(result.base64, bytesToBase64(FIXTURE_ENCODED));
  assert.equal(sha256Hex(base64ToBytes(result.base64)), FIXTURE_ENCODED_SHA256);
});

test('an undecodable photo (HEIC-class) fails before anything is sent', async () => {
  const codec = {
    async decode() { throw new Error('cannot decode'); },
    async encode() { throw new Error('must not be called'); },
  };
  assert.deepEqual(await normalizePhotoFile({ name: 'photo.heic' }, codec),
    { ok: false, reason: 'decode_failed' });
  assert.deepEqual(await normalizePhotoFile(null, codec), { ok: false, reason: 'no_file' });
});

test('a photo still breaking the contract after normalization is too_large', async () => {
  const oversized = new Uint8Array(IMAGE_SIZE_CONTRACT.maxDecodedBytesPerPhoto + 3);
  const codec = {
    async decode() { return { bitmap: {}, width: 100, height: 100 }; },
    async encode() { return new Blob([oversized], { type: 'image/jpeg' }); },
  };
  const result = await normalizePhotoFile({ name: 'noise.jpg' }, codec);
  assert.equal(result.ok, false);
  assert.equal(result.reason, 'too_large');
  assert.ok(result.violations.includes('decoded_too_large'));
});

test('size contract boundaries are checked in their own units', () => {
  const at = (over) => imageContractViolations({ base64: 'AAAA', width: 100, height: 100, ...over });
  assert.deepEqual(at({}), []);
  // base64 characters: 7 MiB of characters exactly is inside, one
  // character over is a violation (unit 1).
  const exactChars = 'A'.repeat(IMAGE_SIZE_CONTRACT.maxBase64CharsPerPhoto);
  assert.ok(!imageContractViolations({ base64: exactChars, width: 1, height: 1 })
    .includes('base64_too_large'));
  assert.ok(imageContractViolations({ base64: exactChars + 'A', width: 1, height: 1 })
    .includes('base64_too_large'));
  // pixels: 16,000,000 exactly is inside, one row over is not (unit 3).
  assert.deepEqual(imageContractViolations({ base64: 'AAAA', width: 4000, height: 4000 }), []);
  assert.ok(imageContractViolations({ base64: 'AAAA', width: 4001, height: 4000 })
    .includes('too_many_pixels'));
  // decoded bytes derive from the base64 length, padding included.
  assert.equal(decodedBytesOfBase64('AAAA'), 3);
  assert.equal(decodedBytesOfBase64('AAA='), 2);
  assert.equal(decodedBytesOfBase64('AA=='), 1);
  assert.equal(decodedBytesOfBase64(''), 0);
});
